#include <iostream>
using namespace std;

int main() {
    int r1, r2, c1, c2, d1, d2;

    while (cin >> r1 >> r2 >> c1 >> c2 >> d1 >> d2) {
        int numerator = r1 - c1 + d2;

        if (numerator % 2 != 0) {
            cout << -1 << '\n';
            continue;
        }

        int b = numerator / 2;
        int a = r1 - b;
        int c = d2 - b;
        int d = c2 - b;

        bool valid =
            a >= 1 && a <= 9 &&
            b >= 1 && b <= 9 &&
            c >= 1 && c <= 9 &&
            d >= 1 && d <= 9 &&
            a != b && a != c && a != d &&
            b != c && b != d && c != d &&
            a + b == r1 &&
            c + d == r2 &&
            a + c == c1 &&
            b + d == c2 &&
            a + d == d1 &&
            b + c == d2;

        if (valid) {
            cout << a << ' ' << b << '\n';
            cout << c << ' ' << d << '\n';
        } else {
            cout << -1 << '\n';
        }
    }

    return 0;
}

#include <iostream>
#include <set>
using namespace std;

int main() {
    int r1, r2, c1, c2, d1, d2;

    while (cin >> r1 >> r2 >> c1 >> c2 >> d1 >> d2) {
        bool found = false;

        for (int a = 1; a <= 9 && !found; ++a) {
            for (int b = 1; b <= 9 && !found; ++b) {
                for (int c = 1; c <= 9 && !found; ++c) {
                    for (int d = 1; d <= 9 && !found; ++d) {
                        set<int> values = {a, b, c, d};

                        if (values.size() == 4 &&
                            a + b == r1 && c + d == r2 &&
                            a + c == c1 && b + d == c2 &&
                            a + d == d1 && b + c == d2) {
                            cout << a << ' ' << b << '\n';
                            cout << c << ' ' << d << '\n';
                            found = true;
                        }
                    }
                }
            }
        }

        if (!found)
            cout << -1 << '\n';
    }

    return 0;
}

